#!/bin/bash
# ============================================================================
# DEPLOY_v2_validate — بوابة التحقق الحية لطبقة الاسترجاع v2
#
# قراءة فقط تمامًا: لا تعديل على admin/app.py، ولا على أي خدمة، ولا على القاعدة
# أو الفهرس. تُضيف مجلد retrieval/ وسكربت القياس فقط، ثم تقيس وتطبع حكمًا واحدًا.
# لا تفعيل إنتاج: علم LEGALMIND_RETRIEVAL_V2 لا يُضبط هنا إطلاقًا.
#
# التشغيل: الصق هذا الملف كاملًا في الطرفية. يعمل بنمط nohup الصامد.
# المتابعة: tail -f /tmp/v2val.log
# ============================================================================
set -u
cd /opt/LegalMind || exit 1

if [ "${1:-}" != "--worker" ]; then
  cat > /tmp/v2val_payload.b64 <<'B64EOF'

B64EOF
  base64 -d /tmp/v2val_payload.b64 > /tmp/v2val.tgz || { echo "B64_FAIL"; exit 1; }
  tar xzf /tmp/v2val.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
  echo "ملفات القياس وُضعت. لا مساس بـapp.py ولا بأي خدمة."
  cp "$0" /tmp/v2val_self.sh 2>/dev/null || true
  nohup bash /tmp/v2val_self.sh --worker > /tmp/v2val.log 2>&1 &
  echo "بدأ القياس في الخلفية. تابع:  tail -f /tmp/v2val.log"
  exit 0
fi

set -a; . /opt/LegalMind/deploy/.env; set +a
echo "=== بوابة التحقق v2 — $(date) ==="
/opt/LegalMind/admin/.venv/bin/python /opt/LegalMind/tools/retrieval_layer_validate.py
echo "=== انتهى — رمز الخروج $? ==="
